// Structured editor for scripts/alchemy_recipes.json.
// Shape mirrors AlchemyRecipes.loadRecipesFromJson:
//   { recipes: [ { input: [{name, count}], outputs: [{name, count}] } ] }
// names are item kinds (or "Carcass of <Mob>" inputs / mob-kind outputs -
// mob resurrection recipes are generated by the engine and must not be
// duplicated here).

import * as api from '../api.js';

export async function alchemyEditor(content, ctx) {
  let doc = {};
  try {
    const data = await api.readModFile(ctx.mod, ctx.file);
    doc = JSON.parse(data.content);
    if (typeof doc !== 'object' || Array.isArray(doc) || !doc) { throw new Error('not an object'); }
  } catch (e) {
    doc = { recipes: [] };
  }
  if (!Array.isArray(doc.recipes)) { doc.recipes = []; }

  const barEl = document.createElement('div');
  barEl.className = 'editor-bar';
  const title = document.createElement('strong');
  title.textContent = 'Alchemy recipes';
  const save = document.createElement('button');
  save.className = 'primary';
  save.textContent = 'Save';
  barEl.appendChild(title);
  barEl.appendChild(save);
  content.appendChild(barEl);

  const status = document.createElement('div');
  content.appendChild(status);

  const list = document.createElement('div');
  content.appendChild(list);

  let dirty = false;
  const markDirty = () => { dirty = true; };

  // one collapsible panel per recipe: a phone shows one recipe at a time
  function recipePanel(recipe) {
    recipe = recipe || {};
    const details = document.createElement('details');
    details.className = 'panel';
    const summary = document.createElement('summary');
    details.appendChild(summary);
    list.appendChild(details);

    const body = document.createElement('div');
    details.appendChild(body);

    function renderSummary() {
      const ins = (recipe.input || []).map(i => (i.count > 1 ? i.count + '× ' : '') + i.name).join(' + ');
      const outs = (recipe.outputs || []).map(o => (o.count > 1 ? o.count + '× ' : '') + o.name).join(' + ');
      summary.textContent = (ins || 'empty recipe') + '  →  ' + (outs || '?');
    }

    function stackRows(labelText, key) {
      const existing = Array.isArray(recipe[key]) ? recipe[key] : [];
      recipe[key] = []; // rows re-add their entries; keep the source refs
      const h = document.createElement('h4');
      h.textContent = labelText;
      body.appendChild(h);
      const table = document.createElement('table');
      table.className = 'pairs';
      body.appendChild(table);
      const addBtn = document.createElement('button');
      addBtn.textContent = '+ ' + key;
      body.appendChild(addBtn);

      function row(entry) {
        entry = entry || {};
        const tr = document.createElement('tr');
        const nameCell = document.createElement('td');
        const countCell = document.createElement('td');
        const delCell = document.createElement('td');
        const nameInput = document.createElement('input');
        nameInput.value = entry.name || '';
        nameInput.placeholder = 'Item kind (e.g. VileEssence)';
        nameInput.style.minWidth = '10em';
        nameCell.appendChild(nameInput);
        const countInput = document.createElement('input');
        countInput.type = 'number';
        countInput.min = 1;
        countInput.step = 1;
        countInput.value = entry.count !== undefined ? entry.count : 1;
        countInput.style.width = '5em';
        countCell.appendChild(countInput);
        const del = document.createElement('button');
        del.textContent = '×';
        del.addEventListener('click', () => {
          tr.remove();
          const i = recipe[key].indexOf(entry);
          if (i >= 0) { recipe[key].splice(i, 1); }
          markDirty(); renderSummary();
        });
        delCell.appendChild(del);
        tr.appendChild(nameCell);
        tr.appendChild(countCell);
        tr.appendChild(delCell);
        table.appendChild(tr);
        nameInput.addEventListener('input', () => { entry.name = nameInput.value; markDirty(); renderSummary(); });
        countInput.addEventListener('input', () => { entry.count = parseInt(countInput.value, 10) || 1; markDirty(); renderSummary(); });
        recipe[key].push(entry);
      }

      addBtn.addEventListener('click', () => { row({}); markDirty(); });
      for (const entry of existing) { row(entry); }
    }

    stackRows('Ingredients (input)', 'input');
    stackRows('Products (outputs)', 'outputs');

    const del = document.createElement('button');
    del.textContent = 'delete recipe';
    del.style.color = '#a55';
    del.addEventListener('click', () => {
      details.remove();
      const i = doc.recipes.indexOf(recipe);
      if (i >= 0) { doc.recipes.splice(i, 1); }
      markDirty();
    });
    body.appendChild(del);

    renderSummary();
    return details;
  }

  for (const recipe of doc.recipes.slice()) { recipePanel(recipe); }

  const add = document.createElement('button');
  add.textContent = '+ recipe';
  add.addEventListener('click', () => {
    const recipe = { input: [], outputs: [] };
    doc.recipes.push(recipe);
    const panelEl = recipePanel(recipe);
    panelEl.open = true;
    markDirty();
  });
  content.appendChild(add);

  const hint = document.createElement('p');
  hint.className = 'hint';
  hint.textContent = 'Names are item kinds (mobsDesc/items kinds). Mob resurrection recipes ' +
    '(carcass + VileEssence) are generated by the engine - do not duplicate them here.';
  content.appendChild(hint);

  save.addEventListener('click', async () => {
    const out = { recipes: [] };
    for (const recipe of doc.recipes) {
      const clean = (arr) => (arr || [])
        .filter(e => e && typeof e.name === 'string' && e.name.trim())
        .map(e => ({ name: e.name.trim(), count: parseInt(e.count, 10) || 1 }));
      const input = clean(recipe.input);
      const outputs = clean(recipe.outputs);
      if (!input.length || !outputs.length) { continue; } // incomplete rows never save
      out.recipes.push({ input, outputs });
    }
    try {
      await api.saveModFile(ctx.mod, ctx.file, JSON.stringify(out, null, 3) + '\n');
      status.className = 'status-ok';
      status.textContent = 'saved (' + out.recipes.length + ' recipes)';
      dirty = false;
      ctx.onSaved && ctx.onSaved();
    } catch (e) {
      status.className = 'status-err';
      status.textContent = e.message;
    }
  });

  return { isDirty: () => dirty };
}
